"""Exercises the six remaining TV2 modules inside integration.py's isolated MySQL/TCP fixture."""
import base64,json
from concurrent.futures import ThreadPoolExecutor

def run(g):
 req0=g['request'];token=g['token'];check=g['check'];sql=g['sql'];actor=g['account'];logstart=len(g['logs'])
 def req(cmd,payload=None):return req0(cmd,payload,token)
 def good(cmd,payload,label):
  a=req(cmd,payload);check(a['success'],label+(' '+str(a.get('error')) if not a['success'] else ''));return a['data']
 def bad(cmd,payload,label):check(not req(cmd,payload)['success'],label)
 def role(name):sql(f"USE ThuVienDAU;UPDATE TaiKhoan SET VaiTro='{name}' WHERE IdTaiKhoan={actor};")
 def title(name,kind='SACH'):
  return good('TV2_TITLE_SAVE',{'idDauTaiLieu':0,'nhanDe':name,'loaiTaiLieu':kind,'maDDC':None,'trangThaiPhanLoai':'CHUA_PHAN_LOAI','viTriTraDDC':None},'create '+name)
 t=title('MARC fixture');tid=t['idDauTaiLieu']
 m=good('TV2_MARC_GET',{'idDauTaiLieu':tid},'new MARC draft metadata')
 control=lambda tag,text:{'NhanTruong':tag,'NoiDungDieuKhien':text}
 data=lambda tag,*subs,i1=' ',i2=' ':{'NhanTruong':tag,'ChiThi1':i1,'ChiThi2':i2,'TruongCon':[{'MaTruongCon':c,'NoiDung':v} for c,v in subs]}
 fields=[control('001','DAU-TEST'),control('005','20261125000000.0'),control('008','261125s2026    vm            000 0 vie  ' .ljust(40)[:40]),data('245',('a','Nhan de MARC'),i1='0',i2='0'),data('020',('a','9786040000012')),data('100',('a','Tac gia thu'),i1='1'),data('264',('b','NXB thu'),('c','2026'),i2='1'),data('650',('a','Chu de A'),i2='4'),data('650',('a','Chu de B'),i2='4')]
 bad('TV2_MARC_SAVE',m|{'dauBieuMARC':'invalid'},'MARC invalid leader rejected')
 bad('TV2_MARC_SAVE',m|{'truong':[{'NhanTruong':'245'}]},'MARC malformed fields rejected')
 m=good('TV2_MARC_SAVE',m|{'truong':fields},'MARC stores ordered repeated fields')
 check(m['truong']==fields and m['trangThai']=='NHAP','MARC roundtrip order and subfields')
 bad('TV2_MARC_SAVE',m|{'phienBan':0},'MARC stale draft rejected')
 checked=good('TV2_MARC_CHECK',{'idDauTaiLieu':tid,'phienBan':m['phienBan'],'phienBanHoSo':m['phienBanHoSo']},'MARC check synchronizes title atomically')
 check(sql(f'USE ThuVienDAU;SELECT NhanDe FROM DauTaiLieu WHERE IdDauTaiLieu={tid};')=='Nhan de MARC','MARC 245 synchronized to title')
 check(checked['trangThai']=='DA_KIEM_TRA' and checked['phienBanDauTaiLieu'] is not None,'MARC checked version snapshot')
 bib=good('TV2_BIBLIO_GET',{'idDauTaiLieu':tid},'shared bibliography DTO')
 check(bib['tacGia']=='Tac gia thu' and bib['isbn']=='9786040000012' and bib['nhaXuatBan']=='NXB thu','bibliography extracts common MARC once')
 edited=good('TV2_MARC_SAVE',checked|{'truong':fields+[data('500',('a','Ghi chu'))]},'editing checked MARC returns to draft')
 check(edited['trangThai']=='NHAP' and edited['phienBanDauTaiLieu'] is None,'MARC edit clears approval metadata')
 invalid=good('TV2_MARC_SAVE',edited|{'truong':fields+[data('245',('a','DUP'),i1='0',i2='0')]},'MARC structural draft may be incomplete')
 bad('TV2_MARC_CHECK',{'idDauTaiLieu':tid,'phienBan':invalid['phienBan'],'phienBanHoSo':invalid['phienBanHoSo']},'MARC duplicate NR field cannot be checked')
 check(sql(f'USE ThuVienDAU;SELECT NhanDe FROM DauTaiLieu WHERE IdDauTaiLieu={tid};')=='Nhan de MARC','failed MARC check rolls title update back')
 # Classified title must use abridged 082 and matching edition/code.
 classified=g['updated']['idDauTaiLieu'];cm=good('TV2_MARC_GET',{'idDauTaiLieu':classified},'MARC classified title fixture')
 cm=good('TV2_MARC_SAVE',cm|{'truong':fields+[data('082',('a','004.1'),('2','23'),i1='0',i2='4')]},'MARC full edition indicator may be saved as draft')
 bad('TV2_MARC_CHECK',{'idDauTaiLieu':classified,'phienBan':cm['phienBan'],'phienBanHoSo':cm['phienBanHoSo']},'MARC check rejects full edition for abridged DDC')
 cm=good('TV2_MARC_SAVE',cm|{'truong':fields+[data('082',('a','004.1'),('2','23'),i1='1',i2='4')]},'MARC abridged 082 saved')
 good('TV2_MARC_CHECK',{'idDauTaiLieu':classified,'phienBan':cm['phienBan'],'phienBanHoSo':cm['phienBanHoSo']},'MARC abridged matching DDC checked')
 p=title('Do an fixture','DO_AN');pid=p['idDauTaiLieu']
 sql("USE ThuVienDAU;INSERT INTO DocGia(MaDinhDanhTruong,HoTen,LoaiDocGia) VALUES('SV-PROJ','SV thu','SINH_VIEN'),('GV-PROJ','GV thu','GIANG_VIEN');")
 sv=int(sql("USE ThuVienDAU;SELECT IdDocGia FROM DocGia WHERE MaDinhDanhTruong='SV-PROJ'"));gv=int(sql("USE ThuVienDAU;SELECT IdDocGia FROM DocGia WHERE MaDinhDanhTruong='GV-PROJ'"))
 check(len(good('TV2_MAJOR_LIST',{},'major picker'))==18,'all 18 school majors available')
 check(len(good('TV2_READER_LIST',{'text':'PROJ'},'reader picker'))==2,'reader references share imported school IDs')
 bad('TV2_PROJECT_GET',{'idDauTaiLieu':tid},'book cannot use project module')
 project=good('TV2_PROJECT_GET',{'idDauTaiLieu':pid},'load empty project')
 project=good('TV2_PROJECT_SAVE',project|{'maNganh':'7480201','khoaHoc':'2023','thanhVien':[{'idDocGia':sv,'vaiTro':'THUC_HIEN'},{'idDocGia':gv,'vaiTro':'HUONG_DAN'}]},'project saves major course and SV/GV roles')
 bad('TV2_PROJECT_SAVE',project|{'phienBan':1},'project stale version rejected')
 bad('TV2_PROJECT_SAVE',project|{'thanhVien':[{'idDocGia':sv,'vaiTro':'HUONG_DAN'}]},'student cannot be a supervisor')
 bad('TV2_PROJECT_SAVE',project|{'thanhVien':[{'idDocGia':sv,'vaiTro':'THUC_HIEN'}]*2},'duplicate project member rejected')
 bad('TV2_PROJECT_SAVE',project|{'maNganh':'9999999'},'unknown major transaction rolled back')
 check(len(good('TV2_PROJECT_GET',{'idDauTaiLieu':pid},'reload project after failed save')['thanhVien'])==2,'failed save preserves project members')
 pdf=b'%PDF-1.4\n'+b'TEST-ONLY-CONTENT\n'*18000+b'%%EOF'
 begin={'idDauTaiLieu':pid,'phienBan':project['phienBan'],'tenTep':'Bao cao thu.pdf','kichThuoc':len(pdf)}
 bad('TV2_FILE_BEGIN',begin|{'tenTep':'../x.pdf'},'upload path traversal rejected')
 bad('TV2_FILE_BEGIN',begin|{'tenTep':'x.exe'},'non-PDF upload rejected')
 bad('TV2_FILE_BEGIN',begin|{'kichThuoc':21*1024*1024},'oversize upload rejected')
 ticket=good('TV2_FILE_BEGIN',begin,'begin chunked PDF upload')
 bad('TV2_FILE_CHUNK',{'maTep':ticket['maTep'],'viTri':1,'duLieu':base64.b64encode(pdf[:10]).decode()},'wrong upload offset rejected')
 bad('TV2_FILE_FINISH',ticket,'incomplete PDF cannot attach')
 for off in range(0,len(pdf),192*1024):ticket=good('TV2_FILE_CHUNK',{'maTep':ticket['maTep'],'viTri':off,'duLieu':base64.b64encode(pdf[off:off+192*1024]).decode()},'upload chunk '+str(off))
 project=good('TV2_FILE_FINISH',ticket,'finish attaches opaque server file identifier')
 check(len(project['danhSachTep'])==1 and '..' not in project['danhSachTep'][0]['duongDan'],'attachment metadata stored in existing JSON')
 restored=b''
 while len(restored)<len(pdf):restored+=base64.b64decode(good('TV2_FILE_READ',{'idDauTaiLieu':pid,'maTep':ticket['maTep'],'viTri':len(restored)},'download chunk')['duLieu'])
 check(restored==pdf,'PDF roundtrip byte for byte over multiple TCP frames')
 bad('TV2_FILE_READ',{'idDauTaiLieu':pid,'maTep':'../secret'},'download path traversal rejected')
 bad('TV2_FILE_READ',{'idDauTaiLieu':tid,'maTep':ticket['maTep']},'file cannot be downloaded via another title')
 invalid_ticket=good('TV2_FILE_BEGIN',begin|{'phienBan':project['phienBan'],'kichThuoc':9},'begin invalid PDF fixture')
 good('TV2_FILE_CHUNK',{'maTep':invalid_ticket['maTep'],'viTri':0,'duLieu':base64.b64encode(b'NOT-A-PDF').decode()},'upload invalid signature fixture')
 bad('TV2_FILE_FINISH',invalid_ticket,'non-PDF signature cannot attach')
 # Independent shelves/copies for inventory, no changes to circulation fixture.
 loc=good('TV2_LOCATION_SAVE',{'idViTri':0,'dayKe':'KK','ngan':'1'},'stock shelf fixture');loc2=good('TV2_LOCATION_SAVE',{'idViTri':0,'dayKe':'KK','ngan':'2'},'stock wrong shelf fixture')
 def copy(code):return good('TV2_COPY_SAVE',{'idBanTaiLieu':0,'idDauTaiLieu':tid,'soDangKyCaBiet':code,'maVach':code,'idViTri':loc['idViTri'],'kyHieuXepGia':'KK THU','trangThai':'SAN_SANG','tinhTrang':'TOT','giaBia':100000,'ngayNhap':'2026-11-25'},'copy fixture '+code)
 copies=[copy('KK-'+str(n)) for n in range(5)]
 def loan(book):
  sql(f"USE ThuVienDAU;INSERT INTO DocGia(MaDinhDanhTruong,HoTen,LoaiDocGia) VALUES('LOAN-{book['idBanTaiLieu']}','SV muon thu','SINH_VIEN');SET @reader=LAST_INSERT_ID();INSERT INTO PhieuMuon(IdDocGia,IdThuThu) VALUES(@reader,{actor});INSERT INTO ChiTietPhieuMuon(IdPhieuMuon,IdDocGia,IdBanTaiLieu,IdDauTaiLieu,HanTra) VALUES(LAST_INSERT_ID(),@reader,{book['idBanTaiLieu']},{tid},'2030-01-01');")
 loan(copies[4])
 stock=good('TV2_STOCK_CREATE',{'tenKiemKe':'Kiem ke THU','idViTri':loc['idViTri']},'snapshot stock expected list excluding open loans');sid=stock['idKiemKe']
 check(stock['soBanDuKien']==4,'open loan excluded from expected stock')
 bad('TV2_STOCK_SCAN',{'idKiemKe':sid,'maVach':'KK-0','idViTriThucTe':loc['idViTri']},'cannot scan planned stock before starting')
 good('TV2_STOCK_ACTION',{'idKiemKe':sid,'trangThai':'DANG_KIEM'},'start stocktake')
 def scan(code,where=loc['idViTri'],damage=False):return good('TV2_STOCK_SCAN',{'idKiemKe':sid,'maVach':code,'idViTriThucTe':where,'huHong':damage},'scan '+code)['ketQua']
 check(scan('KK-0')=='KHOP','stock match')
 check(scan('KK-1',loc2['idViTri'])=='SAI_VI_TRI','stock wrong location')
 check(scan('KK-2',damage=True)=='HU_HONG','stock damaged')
 check(scan('UNKNOWN-EXTRA')=='THUA','stock unknown extra barcode')
 bad('TV2_STOCK_SCAN',{'idKiemKe':sid,'maVach':'KK-0','idViTriThucTe':loc['idViTri']},'duplicate scan rejected')
 loan(copies[3]);bad('TV2_STOCK_ACTION',{'idKiemKe':sid,'trangThai':'HOAN_TAT'},'new open loan blocks stock finish')
 sql(f"USE ThuVienDAU;UPDATE ChiTietPhieuMuon SET TrangThai='DA_TRA',ThoiDiemTra=NOW(),IdNguoiNhanTra={actor} WHERE IdBanTaiLieu={copies[3]['idBanTaiLieu']};")
 good('TV2_STOCK_ACTION',{'idKiemKe':sid,'trangThai':'HOAN_TAT'},'finish stock marks remaining expected copy missing')
 detail=good('TV2_STOCK_DETAIL',{'idKiemKe':sid},'stock export detail');check(len(detail['dong'])==5,'stock detail contains four expected plus unknown extra')
 check(sum(row[7]=='THIEU' for row in detail['dong'])==1,'exactly one missing at finish')
 check(sql(f"USE ThuVienDAU;SELECT TrangThai FROM BanTaiLieu WHERE IdBanTaiLieu={copies[3]['idBanTaiLieu']}")=='SAN_SANG','stock shortage does not change copy to lost/disposed')
 bad('TV2_STOCK_SCAN',{'idKiemKe':sid,'maVach':'AFTER','idViTriThucTe':loc['idViTri']},'completed stock cannot be scanned')
 good('TV2_STOCK_LIST',{},'stock list counts')
 bad('TV2_DISPOSAL_CREATE',{'idBanTaiLieu':copies[4]['idBanTaiLieu'],'lyDo':'dang muon'},'disposal request rejects open loan')
 proposal=good('TV2_DISPOSAL_CREATE',{'idBanTaiLieu':copies[2]['idBanTaiLieu'],'lyDo':'Hu hong','idKiemKe':sid},'cataloger proposes disposal from completed stock')
 bad('TV2_DISPOSAL_CREATE',{'idBanTaiLieu':copies[2]['idBanTaiLieu'],'lyDo':'duplicate'},'duplicate active disposal rejected')
 decision={'idThanhLy':proposal['idThanhLy'],'chapNhan':True,'canCu':'QD THU NGHIEM'}
 bad('TV2_DISPOSAL_DECIDE',decision,'cataloger cannot approve disposal')
 role('QUAN_LY_THU_VIEN')
 bad('TV2_DISPOSAL_CREATE',{'idBanTaiLieu':copies[0]['idBanTaiLieu'],'lyDo':'wrong role'},'manager does not assume cataloger proposal role')
 bad('TV2_DISPOSAL_DECIDE',decision|{'canCu':' '},'disposal needs decision basis')
 good('TV2_DISPOSAL_DECIDE',decision,'manager approves and disposes atomically')
 check(sql(f"USE ThuVienDAU;SELECT TrangThai FROM BanTaiLieu WHERE IdBanTaiLieu={copies[2]['idBanTaiLieu']}")=='THANH_LY','approved disposal persists book status')
 bad('TV2_DISPOSAL_DECIDE',decision,'processed disposal cannot be processed twice')
 good('TV2_DISPOSAL_LIST',{},'disposal list includes processing actors')
 role('BIEN_MUC')
 rejected=good('TV2_DISPOSAL_CREATE',{'idBanTaiLieu':copies[0]['idBanTaiLieu'],'lyDo':'De nghi thu'},'second disposal proposal')
 role('QUAN_LY_THU_VIEN');good('TV2_DISPOSAL_DECIDE',{'idThanhLy':rejected['idThanhLy'],'chapNhan':False,'canCu':'Khong du can cu'},'manager rejects disposal')
 check(sql(f"USE ThuVienDAU;SELECT TrangThai FROM BanTaiLieu WHERE IdBanTaiLieu={copies[0]['idBanTaiLieu']}")=='SAN_SANG','rejected disposal does not change book status')
 role('BIEN_MUC')
 # A loan created after a proposal must still block manager approval; proposal rolls back unchanged.
 pending=good('TV2_DISPOSAL_CREATE',{'idBanTaiLieu':copies[3]['idBanTaiLieu'],'lyDo':'Kiem tra race'},'proposal before a new loan')
 sql(f"USE ThuVienDAU;UPDATE ChiTietPhieuMuon SET TrangThai='DANG_MUON',ThoiDiemTra=NULL,IdNguoiNhanTra=NULL WHERE IdBanTaiLieu={copies[3]['idBanTaiLieu']}")
 role('QUAN_LY_THU_VIEN');bad('TV2_DISPOSAL_DECIDE',{'idThanhLy':pending['idThanhLy'],'chapNhan':True,'canCu':'KHONG DUOC THANH LY'},'loan after proposal blocks approval transaction')
 check(sql(f"USE ThuVienDAU;SELECT TrangThai FROM ThanhLy WHERE IdThanhLy={pending['idThanhLy']}")=='DE_NGHI','failed approval leaves proposal pending')
 report=good('TV2_REPORT',{},'stock grouped report with no filters')
 check(sum(int(x[3]) for x in report['dong'])==int(sql('USE ThuVienDAU;SELECT COUNT(*) FROM BanTaiLieu;')),'report copy totals equal base table, no MARC join inflation')
 check(sum(int(x[2]) for x in report['dong'])==int(sql('USE ThuVienDAU;SELECT COUNT(*) FROM DauTaiLieu;')),'report distinct titles include zero-copy titles')
 report=good('TV2_REPORT',{'tuNgay':'2026-11-25','denNgay':'2026-11-25'},'report inclusive copy accession date range')
 check(sum(int(x[3]) for x in report['dong'])==5,'date report excludes unknown/outside accession dates')
 bad('TV2_REPORT',{'tuNgay':'2026-11-26','denNgay':'2026-11-25'},'report reversed date range rejected')
 bad('TV2_REPORT',{'loaiTaiLieu':"' OR 1=1"},'report validates type filter')
 role('THU_THU')
 good('TV2_BIBLIO_GET',{'idDauTaiLieu':tid},'librarian receives shared bibliography for LT04 printing')
 for cmd,payload in [('TV2_MARC_GET',{'idDauTaiLieu':tid}),('TV2_PROJECT_GET',{'idDauTaiLieu':pid}),('TV2_FILE_READ',{'idDauTaiLieu':pid,'maTep':ticket['maTep']}),('TV2_STOCK_LIST',{}),('TV2_DISPOSAL_LIST',{}),('TV2_REPORT',{})]:bad(cmd,payload,'librarian denied '+cmd)
 role('BIEN_MUC')
 # Serialize competing scans by locking stocktake header; exactly one should commit.
 extra=good('TV2_STOCK_CREATE',{'tenKiemKe':'Quet dong thoi','idViTri':loc['idViTri']},'concurrent scan stock fixture')
 good('TV2_STOCK_ACTION',{'idKiemKe':extra['idKiemKe'],'trangThai':'DANG_KIEM'},'start concurrent scan fixture')
 with ThreadPoolExecutor(max_workers=2) as pool:
  outcomes=list(pool.map(lambda _:req('TV2_STOCK_SCAN',{'idKiemKe':extra['idKiemKe'],'maVach':'KK-0','idViTriThucTe':loc['idViTri']}),range(2)))
 check(sum(x['success'] for x in outcomes)==1,'concurrent scans persist exactly one observation')
 good('TV2_STOCK_ACTION',{'idKiemKe':extra['idKiemKe'],'trangThai':'HUY'},'cancel stock without changing book status')
 for account_role in ['QUAN_TRI','DOC_GIA']:
  role(account_role);bad('TV2_REPORT',{},account_role+' does not inherit catalog privileges')
 role('BIEN_MUC')
 stale=good('TV2_MARC_GET',{'idDauTaiLieu':tid},'MARC title-version conflict fixture')
 sql(f"USE ThuVienDAU;UPDATE DauTaiLieu SET NhanDe='Nhan de nguoi khac vua sua' WHERE IdDauTaiLieu={tid}")
 bad('TV2_MARC_SAVE',stale,'MARC draft cannot overwrite a concurrently changed title context')
 bad('TV2_MARC_CHECK',{'idDauTaiLieu':tid,'phienBan':stale['phienBan'],'phienBanHoSo':stale['phienBanHoSo']},'MARC check rejects stale title version before synchronizing 245')
 check(sql(f'USE ThuVienDAU;SELECT NhanDe FROM DauTaiLieu WHERE IdDauTaiLieu={tid}')=='Nhan de nguoi khac vua sua','MARC conflict preserves the other editor title')
 check(int(sql("USE ThuVienDAU;SELECT COUNT(*) FROM NhatKy WHERE HanhDong='TV2_DISPOSAL_DECIDE' AND JSON_UNQUOTE(JSON_EXTRACT(ChiTiet,'$.after.canCu'))='QD THU NGHIEM'"))==1,'disposal decision audit preserves basis and actor')
 (g['r']/'kiem_tra/TV2_Module_con_lai.txt').write_text('25/11/2026 - remaining TV2 modules, isolated synthetic MySQL/TCP only\n'+'\n'.join(g['logs'][logstart:])+'\n','utf8')
